function twice(v, factor=2) { return v * factor }
page=canvas(size=(100 mm,70 mm),layout_dpi=100)
box=rect(size=(10 mm, 10 mm),fill="#f00")
origin=page.add(box,target=page.top_left)
gap=twice(2 mm)
count=0
for i in range(3) {
  scratch=i
  if i == 1 { continue }
  count=count+1
}
for item in [1,2,3] {
  count=count+item
}
while count < 10 {
  count=count+1
  if count == 9 { break }
}
width=0 mm
if count == 9 and not false {
  width=page.width / 10 + origin.height + 10 px
} else if count == 8 {
  width=1 mm
} else {
  width=2 mm
}
last=page.add(box,size=(width, auto),target=origin.top_right,offset=(gap,0 mm))

page=canvas(size=(10 mm,10 mm))
for i in [1] { local=i }
x=local

page=canvas(size=(20 mm,20 mm))
i=0
while true { i=i+1 }

page=canvas(size=(20 mm,20 mm))
function f(n=0) { return f(n+1) }
x=f()

